  d.undo();CHECK(d.width()==5&&d.height()==4&&d.timeline().state().frames.size()==2&&d.timeline().state().loopSections.empty()&&d.timelineSelection().layers==oldLayers&&d.selectedFrames()==oldFrames&&selectionEqual(d.selection(),mask)&&d.selectionPivotHistory().pivot->x==0&&d.timeline().resolveSurface("b1").surface->offsetX==-4&&d.dirty());d.redo();CHECK(d.width()==11&&d.frame().id==id&&d.timeline().state().loopSections.back().id==loopId&&d.timeline().findCel("B",id)->surface->pixels[1]==0x00030201);
